/* Tailwind v4: `dark:` follows the .dark class on <html>, not the OS. */
@custom-variant dark (&:where(.dark, .dark *));

/* -------------------------------------------------------------------------
   Design tokens — "engineering notebook"
   Warm paper, ink, a single vermilion signal color.
   The --bg-* / --text-* / --accent aliases keep the pages that are not yet
   migrated onto the new palette.
   ------------------------------------------------------------------------- */
:root,
html.light {
  color-scheme: light;
  --paper: #f3eee3;
  --paper-2: #eae2d3;
  --ink: #17140f;
  --ink-soft: #635a4d;
  --rule: #d3c8b6;
  --signal: #c93d1b;
  --signal-soft: rgba(201, 61, 27, 0.07);

  --bg-main: var(--paper);
  --bg-card: #faf5ea;
  --text-main: var(--ink);
  --text-dim: var(--ink-soft);
  --accent: var(--signal);
  --accent-glow: rgba(201, 61, 27, 0.18);
  --border-color: var(--rule);
  --nav-bg: rgba(243, 238, 227, 0.94);
  --terminal-bg: var(--paper-2);
  --canvas-bg: rgba(23, 20, 15, 0.04);
}

html.dark {
  color-scheme: dark;
  --paper: #141210;
  --paper-2: #1d1a16;
  --ink: #f1ebde;
  --ink-soft: #a89c89;
  --rule: #342e26;
  --signal: #ff6a3f;
  --signal-soft: rgba(255, 106, 63, 0.09);

  --bg-main: var(--paper);
  --bg-card: #1a1713;
  --text-main: var(--ink);
  --text-dim: var(--ink-soft);
  --accent: var(--signal);
  --accent-glow: rgba(255, 106, 63, 0.16);
  --border-color: var(--rule);
  --nav-bg: rgba(20, 18, 16, 0.94);
  --terminal-bg: var(--paper-2);
  --canvas-bg: rgba(0, 0, 0, 0.22);
}

@layer base {
  html {
    scroll-behavior: smooth;
  }

  body {
    margin: 0;
    min-height: 100vh;
    font-family: "IBM Plex Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
    background-color: var(--paper);
    color: var(--ink);
    overflow-x: hidden;
    transition: background-color 0.25s ease, color 0.25s ease;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  a {
    color: inherit;
    text-decoration: none;
  }

  ::selection {
    background: var(--signal);
    color: var(--paper);
  }
}

@layer components {
  .font-display {
    font-family: "Instrument Serif", "Iowan Old Style", Georgia, serif;
    font-weight: 400;
  }

  .font-mono-ui {
    font-family: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  }

  .eyebrow {
    font-family: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 0.6875rem;
    line-height: 1.4;
    letter-spacing: 0.18em;
    text-transform: uppercase;
  }
}

@media print {
  .no-print {
    display: none !important;
  }

  body {
    background-color: white !important;
    color: black !important;
    transition: none !important;
  }

  * {
    transition: none !important;
    box-shadow: none !important;
  }
}
